import {weeklySummary,nextWeekPlan} from './workshop-weekly.mjs';
const p=(es,en)=>({es,en});
export function mountWeekly(api){const root=document.createElement('section');root.id='weeklyReview';root.className='challenge-panel';api.before.before(root);
 const el=(tag,text,host)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;},t=x=>x[api.lang()],num=v=>v===null?'—':new Intl.NumberFormat(api.lang(),{maximumFractionDigits:1}).format(v);
 return {render(){root.replaceChildren();const rows=api.results(),summary=weeklySummary(rows),plan=nextWeekPlan(api.evidence?.()??rows,api.goal());
 const examLink=el('a',t(p('Examen semanal de los cuatro talleres →','Weekly four-workshop exam →')),root);examLink.href='workshop-exam.html?lang='+api.lang();
 el('h2',t(p('Tu semana de práctica','Your practice week')),root);el('p',summary.start+' → '+summary.today+' · '+t(p('Semana en curso, lunes a domingo','Current week, Monday to Sunday')),root);
 const metrics=el('div','',root);metrics.className='review-metrics';el('strong',summary.current.count+' '+t(p('retos verificados','verified challenges')),metrics);el('strong',summary.current.days+' '+t(p('días activos','active days')),metrics);el('strong',summary.streak+' '+t(p('días de racha actual','days in your current streak')),metrics);
 el('p',t(p('Repasos personalizados terminados: ','Personalized reviews completed: '))+summary.current.reviews,root);
 const table=el('table','',root);table.className='weekly-comparison';el('caption',t(p('Comparación con los mismos días de la semana anterior: ','Comparison with the same weekdays last week: '))+summary.priorStart+' → '+summary.priorEnd,table);const head=el('tr','',el('thead','',table));for(const text of [t(p('Indicador','Metric')),t(p('Esta semana','This week')),t(p('Anterior','Previous'))])el('th',text,head).scope='col';const body=el('tbody','',table);
 for(const [label,a,b]of [[p('Retos verificados','Verified challenges'),summary.current.count,summary.previous.count],[p('Nota media /100','Average score /100'),summary.current.score,summary.previous.score],[p('Interpretaciones correctas %','Correct interpretations %'),summary.current.accuracy,summary.previous.accuracy]]){const tr=el('tr','',body);el('th',t(label),tr).scope='row';el('td',num(a),tr);el('td',num(b),tr);}
 el('p',t(p('— significa sin datos, no cero. Las notas mezclan niveles: esta comparación describe resultados, no demuestra por sí sola dominio. Datos locales de los últimos 200 resultados; semanas anteriores pueden estar incompletas.','— means no data, not zero. Scores span difficulty levels: this comparison describes results, not proof of mastery. Local data covers the latest 200 results; older weeks may be incomplete.')),root);
 const hard=el('div','',root);hard.className='review-list';for(const [title,items]of [[p('Mediciones que más cuestan','Hardest measurements'),summary.measurements],[p('Diagnósticos que más cuestan','Hardest diagnoses'),summary.diagnoses]]){const section=el('div','',hard);el('h3',t(title),section);if(!items.length)el('p',t(summary.current.count?p('Sin errores registrados en esta categoría esta semana.','No recorded errors in this category this week.'):p('Completa un reto para obtener un resumen personal.','Complete a challenge to build your personal summary.')),section);for(const item of items)el('p',api.name(item)+' · '+item.errors+'/'+item.total+' '+t(item.type==='measurement'?p('interpretaciones incorrectas','incorrect interpretations'):p('casos con un diagnóstico incorrecto','cases with an incorrect diagnosis')),section);}
 el('h3',t(p('Plan de la próxima semana','Next week’s review plan'))+' · '+plan.start+' → '+plan.end,root);
 el('p',t(p('Hasta ','Up to '))+api.goal()+' '+t(p('retos por día, según tu meta. Primero habilidades ya practicadas, ordenadas por tasa de error y vencimiento; después primeras prácticas. Un objetivo se propone una sola vez en este plan.','challenges per day, matching your goal. Previously practised skills come first, ranked by error rate and due date, followed by first practice. Each target appears once in this plan.')),root);
 el('p',t(p('Previsión, no citas guardadas ni recordatorios. Se recalcula al completar retos o cambiar tu meta; un reto puede cubrir varios objetivos. Practicar ahora es un repaso anticipado y cuenta hoy, no en la fecha propuesta.','This is a forecast, not saved appointments or reminders. It updates when you finish challenges or change your goal; one challenge can cover several targets. Practising now is an early review and counts today, not on the suggested date.')),root);
 const grid=el('div','',root);grid.className='review-list';for(const day of plan.days){const card=el('article','',grid);el('h4',new Date(day.day+'T12:00:00').toLocaleDateString(api.lang(),{weekday:'long',month:'short',day:'numeric'}),card);if(!day.entries.length)el('p',t(p('Sin objetivos pendientes en esta previsión. Práctica libre opcional.','No pending targets in this forecast. Optional free practice.')),card);for(const entry of day.entries){const target=el('div','',card);el('p',api.name(entry),target);el('small',t(p('Vence: ','Due: '))+entry.due+' · '+t(entry.seen?p('Refuerzo personal','Personal reinforcement'):p('Primera práctica','First practice')),target);const b=el('button',t(p('Practicar ahora en 3D','Practise now in 3D')),target);b.dataset.weeklyReview=entry.key;b.disabled=api.busy();b.onclick=()=>{if(entry.kind===api.kind){api.start(entry);document.querySelector('#benches').scrollIntoView({block:'start'});}else location.href='workshop.html?case='+entry.kind+'&lang='+api.lang()+'&review='+encodeURIComponent(entry.key)+'#reviewCalendar';};}}
 el('p',plan.scheduled+' '+t(p('retos propuestos · ','suggested challenges · '))+plan.backlog+' '+t(p('objetivos pendientes fuera de la capacidad semanal.','pending targets beyond this week’s capacity.')),root);
 if(api.busy())el('p',t(p('Finaliza o reinicia el reto activo antes de abrir otro.','Finish or reset the active challenge before opening another.')),root);
 }};
}
